import{_ as e,o as a,c as i,ag as s}from"./chunks/framework.BPmc_f4o.js";const u=JSON.parse(`{"title":"Getting Started","description":"Get up and running with Muxit — what it is, what's included, and your first steps.","frontmatter":{"title":"Getting Started","description":"Get up and running with Muxit — what it is, what's included, and your first steps."},"headers":[],"relativePath":"getting-started/index.md","filePath":"getting-started/index.md"}`),r={name:"getting-started/index.md"};function o(n,t,l,h,d,p){return a(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="getting-started-with-muxit" tabindex="-1">Getting Started with Muxit <a class="header-anchor" href="#getting-started-with-muxit" aria-label="Permalink to &quot;Getting Started with Muxit&quot;">​</a></h1><p>Welcome to Muxit — a hardware orchestration platform for controlling instruments, robots, and sensors through a unified interface with automation scripts, real-time dashboards, and AI.</p><h2 id="what-is-muxit" tabindex="-1">What Is Muxit? <a class="header-anchor" href="#what-is-muxit" aria-label="Permalink to &quot;What Is Muxit?&quot;">​</a></h2><p>Muxit gives you a single interface to control all your lab and workshop hardware. Instead of juggling vendor-specific software for each device, you connect everything to Muxit and control it all from one place.</p><p><strong>What you can do:</strong></p><ul><li><strong>Control a power supply</strong> from your browser — set voltage, read current, ramp parameters</li><li><strong>Build a live dashboard</strong> for your CNC machine — position, feed rate, status, all updating in real-time</li><li><strong>Write automation scripts</strong> — ramp a temperature in steps, monitor a threshold, log measurements to a file</li><li><strong>Use AI to control devices</strong> — tell Claude &quot;set the voltage to 12V and monitor the current&quot; and it happens</li><li><strong>Stream a webcam</strong> to a dashboard widget alongside your instrument readings</li><li><strong>Connect IoT sensors</strong> via MQTT — ESP32, Arduino, Home Assistant, Node-RED</li><li><strong>Set up autonomous agents</strong> — an AI that watches temperature and adjusts power automatically</li></ul><p>Muxit runs as a local server on your computer and serves a web-based GUI to your browser. No cloud account required — everything stays on your machine.</p><h2 id="key-concepts" tabindex="-1">Key Concepts <a class="header-anchor" href="#key-concepts" aria-label="Permalink to &quot;Key Concepts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>What It Is</th><th>Example</th></tr></thead><tbody><tr><td><strong>Driver</strong></td><td>Low-level hardware interface that talks to a physical device. JavaScript, Python, or compiled C# DLL</td><td>USB webcam driver, MQTT bridge, serial instrument driver, Python script wrapping a vendor SDK</td></tr><tr><td><strong>Connector</strong></td><td>Wraps a driver with a friendly name, custom methods, and config</td><td><code>psu.js</code> — configures a PSU driver with serial port, adds <code>rampTo()</code> method</td></tr><tr><td><strong>Script</strong></td><td>Sandboxed JavaScript automation program</td><td>Read temperature every second, log it, alert if too high</td></tr><tr><td><strong>Dashboard</strong></td><td>Drag-and-drop layout of live widgets bound to device data</td><td>Gauges, charts, sliders, buttons, video streams</td></tr><tr><td><strong>Agent</strong></td><td>Autonomous AI that plans and executes multi-step goals</td><td>Monitor temperature sensor, reduce power if overheating</td></tr></tbody></table><p>For more definitions, see the <a href="/reference/glossary.html">Glossary</a>.</p><h2 id="what-s-included" tabindex="-1">What&#39;s Included <a class="header-anchor" href="#what-s-included" aria-label="Permalink to &quot;What&#39;s Included&quot;">​</a></h2><p>Muxit ships with a complete demo environment — <strong>no hardware needed</strong> to start exploring:</p><ul><li><strong>TestDevice</strong> — a simulated instrument with temperature, voltage, counters, and more. Always available, doesn&#39;t count against connector limits</li><li><strong>Example scripts</strong> — <code>hello.js</code> (basic logging), <code>examples/sinewave.js</code> (animated dashboard data), <code>examples/psu-voltage-ramp.js</code> and <code>examples/threshold-alert.js</code> (instrument control &amp; alerting), plus a numbered <code>tutorials/</code> series (<code>01-hello-world.js</code> … <code>10-ai-vision.js</code>)</li><li><strong>Example dashboards</strong> — <code>demo.dashboard.json</code> (interactive gauges, sliders, charts), <code>test-device.dashboard.json</code> (full device control panel)</li><li><strong>Built-in drivers</strong> — Webcam, ONVIF IP camera, FileAccess (sandboxed file I/O), MqttBridge (IoT integration), WebhookNotifier, EmailNotifier</li><li><strong>Example agents</strong> — temperature-monitor (auto-reduce power), pick-and-place (robot coordination)</li></ul><hr><h2 id="_5-minute-quickstart" tabindex="-1">5-Minute Quickstart <a class="header-anchor" href="#_5-minute-quickstart" aria-label="Permalink to &quot;5-Minute Quickstart&quot;">​</a></h2><h3 id="_1-install-and-start" tabindex="-1">1. Install and Start <a class="header-anchor" href="#_1-install-and-start" aria-label="Permalink to &quot;1. Install and Start&quot;">​</a></h3><p>Install the latest release — no prerequisites, the binary is self-contained.</p><p><strong>Windows</strong> (PowerShell):</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">irm https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">raw.githubusercontent.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">muxit</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">io</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">muxit</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">main</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">install.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre></div><p><strong>macOS / Linux</strong> (bash) — the same script detects your OS and CPU architecture:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/muxit-io/muxit/main/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><p>Then start Muxit:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">muxit</span></span></code></pre></div><p>Your browser opens to <strong><a href="http://127.0.0.1:8765" target="_blank" rel="noreferrer">http://127.0.0.1:8765</a></strong>. See the <a href="/getting-started/installation.html">Installation Guide</a> for detailed setup.</p><h3 id="_2-explore-the-hardware-panel" tabindex="-1">2. Explore the Hardware Panel <a class="header-anchor" href="#_2-explore-the-hardware-panel" aria-label="Permalink to &quot;2. Explore the Hardware Panel&quot;">​</a></h3><p>Click the <strong>plug icon</strong> in the left Activity Bar to open the Hardware panel. You&#39;ll see the <strong>test-device</strong> connector with live properties:</p><ul><li><strong>temperature</strong> — a simulated temperature value</li><li><strong>label</strong> — a text label you can change</li><li><strong>enabled</strong> — a boolean toggle</li><li><strong>threshold</strong> — a numeric threshold</li><li><strong>count</strong> — an incrementing counter</li></ul><p>These values update in real-time through polling.</p><h3 id="_3-open-a-dashboard" tabindex="-1">3. Open a Dashboard <a class="header-anchor" href="#_3-open-a-dashboard" aria-label="Permalink to &quot;3. Open a Dashboard&quot;">​</a></h3><p>In the Explorer sidebar (files icon), expand <code>dashboards/</code> and click <strong>demo.dashboard.json</strong>. You&#39;ll see a live dashboard with:</p><ul><li>Gauge widgets showing sine/cosine waves</li><li>Sliders you can drag to change values</li><li>A chart plotting data over time</li><li>An indicator light showing running state</li></ul><h3 id="_4-run-a-script" tabindex="-1">4. Run a Script <a class="header-anchor" href="#_4-run-a-script" aria-label="Permalink to &quot;4. Run a Script&quot;">​</a></h3><p>In the Explorer sidebar, expand <code>scripts/examples/</code> and click <strong>sinewave.js</strong>. Click the <strong>Run</strong> button in the editor toolbar. Watch the dashboard come alive — the script drives the gauge and chart values with animated sine waves.</p><p>Click <strong>Stop</strong> to end the script.</p><h3 id="_5-try-the-ai-chat-optional" tabindex="-1">5. Try the AI Chat (Optional) <a class="header-anchor" href="#_5-try-the-ai-chat-optional" aria-label="Permalink to &quot;5. Try the AI Chat (Optional)&quot;">​</a></h3><p>Click the <strong>chat icon</strong> in the Activity Bar to open the AI Chat sidebar. With an active Muxit license, try:</p><ul><li><em>&quot;What devices are connected?&quot;</em></li><li><em>&quot;Read the test device temperature&quot;</em></li><li><em>&quot;Set the threshold to 75&quot;</em></li></ul><hr><h2 id="choose-your-path" tabindex="-1">Choose Your Path <a class="header-anchor" href="#choose-your-path" aria-label="Permalink to &quot;Choose Your Path&quot;">​</a></h2><h3 id="i-have-lab-instruments" tabindex="-1">&quot;I have lab instruments&quot; <a class="header-anchor" href="#i-have-lab-instruments" aria-label="Permalink to &quot;&quot;I have lab instruments&quot;&quot;">​</a></h3><p>You have SCPI-compatible instruments (oscilloscopes, power supplies, multimeters) connected via USB/serial or TCP/IP.</p><p><strong>Start here:</strong></p><ol><li><a href="/examples/first-connector.html">Your First Connector</a> — learn the connector config format</li><li><a href="/guides/connectors.html">Connector Guide</a> — transports, serial/TCP setup, real hardware examples</li><li><a href="/reference/driver-sdk.html">Driver SDK</a> — build a custom driver for your instrument</li></ol><h3 id="i-already-have-a-python-script-that-talks-to-my-device" tabindex="-1">&quot;I already have a Python script that talks to my device&quot; <a class="header-anchor" href="#i-already-have-a-python-script-that-talks-to-my-device" aria-label="Permalink to &quot;&quot;I already have a Python script that talks to my device&quot;&quot;">​</a></h3><p>A vendor SDK, an existing analysis script, a model from huggingface — anything you&#39;d rather not rewrite in JavaScript.</p><p><strong>Start here:</strong></p><ol><li><a href="/reference/driver-sdk-python.html#generic-python-driver">Python Driver SDK — Generic <code>Python</code> driver</a> — drop a <code>.py</code> into <code>workspace/python/</code>, point a connector at it, done. No <code>Driver</code> class, no JSON-RPC.</li><li><a href="/reference/driver-sdk-python.html#structure">Python Driver SDK — Structure</a> — for when you outgrow the generic driver and want a typed, packaged <code>.muxdriver</code>.</li><li><a href="/guides/connectors.html">Connector Guide</a> — wire your Python functions up as properties and methods.</li></ol><h3 id="i-have-a-cnc-3d-printer-or-robot" tabindex="-1">&quot;I have a CNC, 3D printer, or robot&quot; <a class="header-anchor" href="#i-have-a-cnc-3d-printer-or-robot" aria-label="Permalink to &quot;&quot;I have a CNC, 3D printer, or robot&quot;&quot;">​</a></h3><p>You have motion-control hardware that communicates over serial (G-code/GRBL) or TCP.</p><p><strong>Start here:</strong></p><ol><li><a href="/guides/connectors.html">Connector Guide</a> — see the G-code/GRBL CNC example</li><li><a href="/guides/dashboards.html">Dashboard Guide</a> — build a control panel with position display, buttons, terminal</li><li><a href="/examples/first-script.html">Your First Script</a> — automate motion sequences</li></ol><h3 id="i-have-iot-sensors" tabindex="-1">&quot;I have IoT sensors&quot; <a class="header-anchor" href="#i-have-iot-sensors" aria-label="Permalink to &quot;&quot;I have IoT sensors&quot;&quot;">​</a></h3><p>You have ESP32, Arduino, Tasmota, or Home Assistant devices communicating via MQTT.</p><p><strong>Start here:</strong></p><ol><li><a href="/guides/mqtt-iot.html">MQTT &amp; IoT Guide</a> — connect to an MQTT broker, subscribe to topics, display data</li><li><a href="/guides/dashboards.html">Dashboard Guide</a> — build a sensor dashboard</li><li><a href="/examples/first-script.html">Your First Script</a> — automate based on sensor readings</li></ol><h3 id="i-want-to-use-ai-to-control-hardware" tabindex="-1">&quot;I want to use AI to control hardware&quot; <a class="header-anchor" href="#i-want-to-use-ai-to-control-hardware" aria-label="Permalink to &quot;&quot;I want to use AI to control hardware&quot;&quot;">​</a></h3><p>You want Claude, GPT-4, or another LLM to control your devices.</p><p><strong>Start here:</strong></p><ol><li><a href="/guides/ai.html">AI &amp; Voice Guide</a> — set up the Chat Panel or MCP server</li><li><a href="/guides/ai.html#agent-mode">AI &amp; Voice Guide — Agents</a> — autonomous AI with safety boundaries</li></ol><h3 id="i-just-want-to-explore" tabindex="-1">&quot;I just want to explore&quot; <a class="header-anchor" href="#i-just-want-to-explore" aria-label="Permalink to &quot;&quot;I just want to explore&quot;&quot;">​</a></h3><p>No hardware yet — you want to learn what Muxit can do.</p><p><strong>Start here:</strong></p><ol><li><a href="/getting-started/ui-tour.html">UI Tour</a> — understand the interface</li><li><a href="/examples/first-script.html">Your First Script</a> — write a script using the TestDevice</li><li><a href="/examples/first-dashboard.html">Your First Dashboard</a> — build a dashboard with live widgets</li><li><a href="/examples/first-connector.html">Your First Connector</a> — create a connector config</li></ol><hr><h2 id="running-muxit" tabindex="-1">Running Muxit <a class="header-anchor" href="#running-muxit" aria-label="Permalink to &quot;Running Muxit&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">muxit</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # Start the server and open the browser</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">muxit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --nogui</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # Start without opening the browser</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">muxit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-tray</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # Start without the system tray icon</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">muxit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port=9000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # Use a custom port</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">muxit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cli</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # CLI mode (driver testing REPL)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">muxit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mcp</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # MCP server (for Claude Code / Desktop)</span></span></code></pre></div><p>Then open <strong><a href="http://127.0.0.1:8765" target="_blank" rel="noreferrer">http://127.0.0.1:8765</a></strong> in your browser.</p><h2 id="file-structure" tabindex="-1">File Structure <a class="header-anchor" href="#file-structure" aria-label="Permalink to &quot;File Structure&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>workspace/</span></span>
<span class="line"><span>├── connectors/    ← device configurations (.js)</span></span>
<span class="line"><span>├── scripts/       ← automation scripts (.js)</span></span>
<span class="line"><span>├── drivers/       ← driver files (.driver.js, .driver.py, .muxdriver)</span></span>
<span class="line"><span>├── python/        ← Python scripts that connectors expose as devices (.py + optional .requirements.txt)</span></span>
<span class="line"><span>├── dashboards/    ← dashboard layouts (.dashboard.json)</span></span>
<span class="line"><span>├── agents/        ← agent config files (.agent.json)</span></span>
<span class="line"><span>├── data/          ← sandboxed file storage (FileAccess driver)</span></span>
<span class="line"><span>└── config/        ← server settings (server.json)</span></span></code></pre></div><p>The filename of each connector, script, or dashboard becomes its name in Muxit. For example, <code>connectors/psu.js</code> creates a connector called &quot;psu&quot; that you access with <code>connector(&quot;psu&quot;)</code> in scripts.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/getting-started/system-requirements.html">System Requirements</a> — supported platforms, hardware, network</li><li><a href="/getting-started/installation.html">Installation</a> — detailed setup for Windows, macOS, and Linux</li><li><a href="/getting-started/ui-tour.html">UI Tour</a> — learn the interface</li><li><a href="/examples/first-script.html">Your First Script</a> — write and run a script</li><li><a href="/examples/first-dashboard.html">Your First Dashboard</a> — build a live dashboard</li><li><a href="/examples/first-connector.html">Your First Connector</a> — configure a device</li><li><a href="/guides/scripts.html">Script Guide</a> — all script API functions</li><li><a href="/guides/connectors.html">Connector Guide</a> — connector config format</li><li><a href="/guides/dashboards.html">Dashboard Guide</a> — widgets and data binding</li><li><a href="/guides/ai.html">AI Guide</a> — AI chat, voice, MCP, agents</li><li><a href="/guides/python-connectors.html">Python Connectors Guide</a> — wrap a Python script as a Muxit connector</li><li><a href="/reference/driver-sdk.html">Driver SDK</a> — write a custom driver in JavaScript, Python, or C#</li><li><a href="/guides/troubleshooting.html">Troubleshooting</a> — common issues and solutions</li></ul>`,72)])])}const g=e(r,[["render",o]]);export{u as __pageData,g as default};
